import { DatabaseSync } from "node:sqlite";

const db = new DatabaseSync('boards.db');

interface Board {
  id: number;
  title: string;
}

interface Card {
  id: number;
  boardId: number;
  content: string;
}

function createBoard(title: string): void {
  const sql = 'INSERT INTO boards (title) VALUES (?)';
  db.run(sql, [title]);
}

function getBoards(): Board[] {
  const sql = 'SELECT * FROM boards';
  const stmt = db.prepare(sql);
  return stmt.all() as unknown as Board[];
}

function getCards(boardId: number): Card[] {
  const sql = 'SELECT * FROM cards WHERE boardId = ?';
  const stmt = db.prepare(sql);
  return stmt.all([boardId]) as unknown as Card[];
}

function createCard(boardId: number, content: string): void {
  const sql = 'INSERT INTO cards (boardId, content) VALUES (?, ?)';
  db.run(sql, [boardId, content]);
}

export { db, createBoard, getBoards, getCards, createCard };

import type { FC } from "react";

interface Board {
  id: number;
  title: string;
}

interface Card {
  id: number;
  title: string;
  description: string;
  boardId: number;
}

const fetchBoards = async (): Promise<Board[]> => {
  const response = await fetch("/api/boards-api/boards");
  if (!response.ok) {
    throw new Error("Failed to fetch boards");
  }
  return await response.json();
};

const fetchCardsByBoardId = async (boardId: number): Promise<Card[]> => {
  const response = await fetch(`/api/boards-api/boards/${boardId}/cards`);
  if (!response.ok) {
    throw new Error("Failed to fetch cards");
  }
  return await response.json();
};

const BoardView: FC = () => {
  const [boards, setBoards] = React.useState<Board[]>([]);
  const [loading, setLoading] = React.useState<boolean>(true);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    const loadBoards = async () => {
      try {
        const fetchedBoards = await fetchBoards();
        setBoards(fetchedBoards);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    loadBoards();
  }, []);

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  return (
    <div>
      {boards.map((board) => (
        <div key={board.id} style={{ border: '1px solid black', padding: '10px' }}>
          <h2>{board.title}</h2>
          <button onClick={() => fetchCardsByBoardId(board.id)}>Load Cards</button>
        </div>
      ))}
    </div>
  );
};

export { BoardView };

