  paymentStatus: string;
}

const db = new DatabaseSync('orders.db');

function createTable(): void {
  db.exec(
    `CREATE TABLE IF NOT EXISTS orders (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      customerId INTEGER,
      lineItems TEXT,
      paymentStatus TEXT
    )`
  );
}

function insertOrder(order: Order): void {
  db.run(
    'INSERT INTO orders (customerId, lineItems, paymentStatus) VALUES (?, ?, ?)',
    [order.customerId, order.lineItems, order.paymentStatus]
  );
}

function getOrderById(id: number): Order | null {
  const stmt = db.prepare('SELECT * FROM orders WHERE id = ?');
  const result = stmt.get(id) as unknown as Order | null;
  return result;
}

function getOrdersByCustomerId(customerId: number): Order[] {
  const stmt = db.prepare('SELECT * FROM orders WHERE customerId = ?');
  const results = stmt.all(customerId) as unknown as Order[];
  return results;
}

function updatePaymentStatus(id: number, paymentStatus: string): void {
  db.run(
    'UPDATE orders SET paymentStatus = ? WHERE id = ?',
    [paymentStatus, id]
  );
}

function deleteOrder(id: number): void {
  db.run('DELETE FROM orders WHERE id = ?', [id]);
}

