import type { FC } from 'react';

interface RefundFormProps {
  customerId: string;
}

const RefundPanel: FC<RefundFormProps> = ({ customerId }) => {
  const [refundReason, setRefundReason] = React.useState('');
  const [refundLogs, setRefundLogs] = React.useState([]);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  const fetchRefundLogs = async () => {
    try {
      const response = await fetch(`/api/customer-lookup-api/customer-lookup/${customerId}/refund-logs`);
      if (!response.ok) {
        throw new Error('Failed to fetch refund logs');
      }
      const data = await response.json();
      setRefundLogs(data);
    } catch (err) {
      setError(err.message);
    }
  };

  const handleRefund = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/refund-api/refund', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          customerId,
          reason: refundReason,
        }),
      });
      if (!response.ok) {
        throw new Error('Failed to issue refund');
      }
      setRefundReason('');
      fetchRefundLogs();
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  React.useEffect(() => {
    fetchRefundLogs();
  }, [customerId]);

  return (
    <div>
      <h2>Issue Refund</h2>
      <textarea
        value={refundReason}
        onChange={(e) => setRefundReason(e.target.value)}
        placeholder='Enter refund reason'
      />
      <button onClick={handleRefund} disabled={loading || !refundReason}>Submit Refund</button>
      {loading && <p>Loading...</p>}
      {error && <p>Error: {error}</p>}
      <h3>Refund Logs</h3>
      <ul>
        {refundLogs.map((log, index) => (
          <li key={index}>{log}</li>
        ))}
      </ul>
    </div>
  );
};

export { RefundPanel };

import { DatabaseSync } from "node:sqlite";

const db = new DatabaseSync('./finance.db');

interface Transaction {
  id: number;
  amount: number;
  merchant: string;
  date: Date;
  category: string;
}

function createTable(): void {
  const sql = `
    CREATE TABLE IF NOT EXISTS transactions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      amount REAL NOT NULL,
      merchant TEXT NOT NULL,
      date DATETIME NOT NULL,
      category TEXT NOT NULL
    );
  `;
  db.exec(sql);
}

function insertTransaction(amount: number, merchant: string, date: Date, category: string): number {
  const sql = 'INSERT INTO transactions (amount, merchant, date, category) VALUES (?, ?, ?, ?)';
  const stmt = db.prepare(sql);
  const result = stmt.run(amount, merchant, date.toISOString(), category);
  return result.lastInsertRowid as number;
}

function getTransactions(): Transaction[] {
  const sql = 'SELECT * FROM transactions';
  const stmt = db.prepare(sql);
  const rows = stmt.all() as unknown as Record<string, any>[];
  return rows.map(row => ({
    id: row.id as number,
    amount: row.amount as number,
    merchant: row.merchant as string,
    date: new Date(row.date as string),
    category: row.category as string
  }));
}

function getTransactionById(id: number): Transaction | null {
  const sql = 'SELECT * FROM transactions WHERE id = ?';
  const stmt = db.prepare(sql);
  const row = stmt.get(id) as unknown as Record<string, any> | undefined;
  if (!row) return null;
  return {
    id: row.id as number,
    amount: row.amount as number,
    merchant: row.merchant as string,
    date: new Date(row.date as string),
    category: row.category as string
  };
}

export { db, createTable, insertTransaction, getTransactions, getTransactionById };

