function updateWorkout(id: number, workout: Partial<Omit<Workout, 'id'>>): void {
  const setClause = Object.keys(workout).map(key => `${key} = ?`).join(', ');
  const params = [setClause, ...Object.values(workout), id];
  const sql = `UPDATE workouts SET ${setClause} WHERE id = ?`;
  db.prepare(sql).run(params);
}

function deleteWorkout(id: number): void {
  const sql = 'DELETE FROM workouts WHERE id = ?';
  db.prepare(sql).run(id);
}

