const DeviceControlPanel: FC = () => {
  const [devices, setDevices] = React.useState<Device[]>([]);

  React.useEffect(() => {
    fetch('/api/device-control-api/devices')
      .then(response => response.json())
      .then(data => setDevices(data));
  }, []);

  const toggleDevice = (deviceId: number) => {
    fetch(`/api/device-control-api/devices/${deviceId}/state`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ state: !devices.find(d => d.id === deviceId)?.state })
    });
  };

  const adjustSlider = (deviceId: number, newState: number) => {
    fetch(`/api/device-control-api/devices/${deviceId}/state`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ state: newState })
    });
  };

  return (
    <div>
      {devices.map(device => (
        <div key={device.id}>
          {device.type === 'light' && (
            <button onClick={() => toggleDevice(device.id)}>{device.state ? 'Turn Off' : 'Turn On'}</button>
          )}
          {device.type === 'thermostat' && (
            <input
              type='range'
              min='0'
              max='100'
              value={device.state}
              onChange={(e) => adjustSlider(device.id, Number(e.target.value))}
            />
          )}
          {device.type === 'lock' && (
            <button onClick={() => toggleDevice(device.id)}>{device.state ? 'Unlock' : 'Lock'}</button>
          )}
        </div>
      ))}
    </div>
  );
};

export { DeviceControlPanel };

