import { DatabaseSync } from "node:sqlite";

const db = new DatabaseSync('library.db');

interface Book {
  id: number;
  title: string;
  author: string;
  copy_count: number;
}

function createTable(): void {
  const sql = `CREATE TABLE IF NOT EXISTS books (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    author TEXT NOT NULL,
    copy_count INTEGER NOT NULL
  )`;
  db.exec(sql);
}

function insertBook(title: string, author: string, copyCount: number): number {
  const sql = 'INSERT INTO books (title, author, copy_count) VALUES (?, ?, ?)';
  const stmt = db.prepare(sql);
  stmt.run(title, author, copyCount);
  return stmt.lastInsertRowid as number;
}

function getBooks(): Book[] {
  const sql = 'SELECT * FROM books';
  const stmt = db.prepare(sql);
  return stmt.all() as unknown as Book[];
}

function getBookById(id: number): Book | null {
  const sql = 'SELECT * FROM books WHERE id = ?';
  const stmt = db.prepare(sql);
  return stmt.get(id) as unknown as Book | null;
}

function updateBook(id: number, title: string, author: string, copyCount: number): boolean {
  const sql = 'UPDATE books SET title = ?, author = ?, copy_count = ? WHERE id = ?';
  const stmt = db.prepare(sql);
  const result = stmt.run(title, author, copyCount, id);
  return result.changes > 0;
}

function deleteBook(id: number): boolean {
  const sql = 'DELETE FROM books WHERE id = ?';
  const stmt = db.prepare(sql);
  const result = stmt.run(id);
  return result.changes > 0;
}

export { db, createTable, insertBook, getBooks, getBookById, updateBook, deleteBook };

