    fetch('/api/catalogue-api/books')
      .then(response => response.json())
      .then(data => setBooks(data));
  }, []);

  const handleAddBook = async (title: string, author: string, copies: number) => {
    const newBook = { title, author, copies };
    await fetch('/api/catalogue-api/books', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(newBook)
    });
    setBooks([...books, newBook]);
  };

  const handleUpdateBook = async (id: number, copies: number) => {
    await fetch(`/api/catalogue-api/books/${id}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ copies })
    });
