}

function createTable(): void {
  const sql = `
    CREATE TABLE IF NOT EXISTS stock_levels (
      sku TEXT PRIMARY KEY,
      location_id INTEGER,
      current_quantity INTEGER,
      reorder_threshold INTEGER
    )
  `;
  db.exec(sql);
}

function insertStockLevel(stockLevel: StockLevel): void {
  const sql = 'INSERT INTO stock_levels (sku, location_id, current_quantity, reorder_threshold) VALUES (?, ?, ?, ?)';
  db.prepare(sql).run(
    stockLevel.sku,
    stockLevel.location_id,
    stockLevel.current_quantity,
    stockLevel.reorder_threshold
  );
}

function updateStockLevel(sku: string, stockLevel: Partial<StockLevel>): void {
  const setClause = Object.keys(stockLevel)
    .map(key => `${key} = ?`) // Assuming all properties are optional
    .join(', ');
  const params = [setClause, ...Object.values(stockLevel), sku];
  const sql = `UPDATE stock_levels SET ${setClause} WHERE sku = ?`;
  db.prepare(sql).run(params);
}

function getStockLevel(sku: string): StockLevel | null {
  const sql = 'SELECT * FROM stock_levels WHERE sku = ?';
  const result = db.prepare(sql).get(sku) as unknown as StockLevel | null;
  return result;
}

function getAllStockLevels(): StockLevel[] {
  const sql = 'SELECT * FROM stock_levels';
  const results = db.prepare(sql).all() as unknown as StockLevel[];
  return results;
}

