  const [skusBelowThreshold, setSkusBelowThreshold] = React.useState<SkuLevel[]>([]);

  React.useEffect(() => {
    fetch('/api/inventory-api/levels')
      .then(response => response.json())
      .then(data => {
        const skusBelowThresholdData = data.filter(item => item.level < item.reorderThreshold);
        setSkusBelowThreshold(skusBelowThresholdData);
      });
  }, []);

  return (
    <div>
      <h1>Reorder Queue</h1>
      <ul>
        {skusBelowThreshold.map(sku => (
          <li key={sku.sku}>{sku.sku}</li>
        ))}
      </ul>
    </div>
  );
};

export { ReorderQueue };

