  description: string;
  time: string;
  capacity: number;
}

const db = new DatabaseSync('volunteer-coordination-tool.db');

function createShift(description: string, time: string, capacity: number): void {
  const sql = 'INSERT INTO shifts (description, time, capacity) VALUES (?, ?, ?)';
  db.prepare(sql).run(description, time, capacity);
}

function getShiftById(id: number): Shift | null {
  const sql = 'SELECT * FROM shifts WHERE id = ?';
  const result = db.prepare(sql).get(id) as unknown as Shift;
  return result || null;
}

function getAllShifts(): Shift[] {
  const sql = 'SELECT * FROM shifts';
  const results = db.prepare(sql).all() as unknown as Shift[];
  return results;
}

function updateShift(id: number, description: string, time: string, capacity: number): void {
  const sql = 'UPDATE shifts SET description = ?, time = ?, capacity = ? WHERE id = ?';
  db.prepare(sql).run(description, time, capacity, id);
}

function deleteShift(id: number): void {
  const sql = 'DELETE FROM shifts WHERE id = ?';
  db.prepare(sql).run(id);
}

export { db, createShift, getShiftById, getAllShifts, updateShift, deleteShift };

